python3 -c "
import json
with open('/app/resources/treasury_bulletin_1972_05.json') as f:
    data = json.load(f)
# Find elements containing '13-week' or 'Amount outstanding'
for i, elem in enumerate(data['document']['elements']):
    if elem.get('description'):
        if '13-week' in str(elem['description']).lower() or 'amount outstanding' in str(elem['description']).lower():
            print(f'Element {i}: {elem[\"description\"][:200] if len(str(elem[\"description\"])) > 200 else elem[\"description\"]}')
"
